def source(sid,publisher,title,url,locator,published,terms=None,basis='Facts-only extraction; source prose and graphics are not republished',version=None):
 s=dict(sourceId=sid,publisher=publisher,title=title,url=url,locator=locator,version=version,publishedAt=published,retrievedAt=DATE,reuse=dict(basis=basis,termsUrl=terms,attribution=f'{publisher}. {title}. Accessed {DATE}.',verified=True,notes='Metadata and brief independently written factual records only; no implication of endorsement. Not a claim that the whole source is openly licensed.'))
 SOURCES[sid]=s;return sid
def row(id,name,value,unit,period,sid,locator,geo=None,status='categorical',notes='Selected record; not an incidence estimate.',**extra):
 return dict(id=id,entityId=id,name=name,value=value,unit=unit,period=period,sourceId=sid,sourceLocator=locator,status=status,qualifier=None,geographicId=geo,lat=None,lon=None,notes=notes,**extra)
def dataset(id,title,cids,rows,sids,scope,omitted,ai='direct',mode='categorical',denom='Not applicable: categorical records, not a rate',uncertainty='Selected primary-source records are not an exhaustive census; absence of a record does not mean absence of activity.',transform=None):
 d=dict(datasetId=id,id=id,title=title,conceptIds=cids,rows=rows,columns={k: {'value':'Measured value or explicit category; never visual magnitude unless numeric and appropriate','period':'Observation/event period; not retrieval date','geographicId':'ISO 3166 alpha-3 or explicit named area; null for non-geographic records','lat':'Null: no invented point location','lon':'Null: no invented point location','sourceLocator':'Exact section/table/row in cited primary source'}.get(k,k+' field; see row notes') for k in dict.fromkeys(k for r in rows for k in r)},unit=rows[0]['unit'],denominator=denom,geography=dict(mode=mode,unit='Source-defined jurisdiction' if mode=='geographic' else 'Abstract categorical sphere',definition='Country means jurisdiction or organisation affiliation, never exposure or event origin.' if mode=='geographic' else 'Records are not geographically allocated.',anchorRule='Country polygon or explicitly labelled jurisdiction; null coordinates must remain null.' if mode=='geographic' else 'Abstract sphere cells only. Do not place records on country boundaries.'),time=dict(observationStart=min(r['period'] for r in rows),observationEnd=max(r['period'] for r in rows),publishedAt=None,retrievedAt=DATE,updateCadence='Manual revalidation before implementation and after source updates'),sources=[SOURCES[s] for s in sids],coverage=dict(population=scope,included=f'{len(rows)} populated records; '+scope,omitted=omitted,missingness='Unlisted entities are missing, not zero.'),uncertainty=uncertainty,transform=transform or dict(type='manual',description='Manual transcription of factual values/categories; no interpolation, imputation or causal inference.',codePath='research/scripts/governance_build.py',inputReferences=[SOURCES[s]['url'] for s in sids],validation='Each row carries a source locator; categorical values separately label plans, policies and observed events.'),verification=dict(status='researcher-checked',method='Read primary source and compare each extracted record to its named source location.',checkedRows=[r['id'] for r in rows],evidencePaths=['research/sources/governance-source-index.json'],reviewer='governance_research',checkedAt=DATE),aiRelationship=ai,scoring=dict(type='none',method='none',reason='No universal extremity or impact score is supported by these data.'),forecast=dict(type='none',method='none',reason='No validated forecast was supplied. Policy intentions and planned installations are not predictions.'))
 DATASETS.append(d);return id

def propose(cid,did,question,claim,verdict='reframe-ready',limitations=None):
 PROPOSALS[cid]=dict(datasetIds=[did],proposedQuestion=question,claim=claim,verdict=verdict,limitations=limitations or ['Only the stated extract and period are supported; no global causal ranking.'])

