def save():
 for d in DATASETS:
  (ROOT/'datasets'/f"{d['datasetId']}.json").write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
 (ROOT/'sources/governance-source-index.json').write_text(json.dumps(list(SOURCES.values()),indent=2,ensure_ascii=False)+'\n')
 if '--datasets-only' in sys.argv:return
 audits=[]
 for c in CONCEPTS:
  p=PROPOSALS.get(c['id']); ds=[d for d in DATASETS if p and d['datasetId'] in p['datasetIds']]
  audits.append(dict(conceptId=c['id'],originalSourceUrl=c['url'],originalQuestion=c['question'],proposedTitle=c['newTitle'],proposedQuestion=p['proposedQuestion'] if p else c['question'],claim=p['claim'] if p else 'No validated implementation dataset accepted yet.',sourceConnection=c['sourceConcept']+' — '+c['connection'],reframeReason=('The available primary records support the narrower stated question, not the full global or causal original.' if p and p['verdict']=='reframe-ready' else None),aiRelationship=dict(**{'class':ds[0]['aiRelationship'] if ds else 'illustrative'},justification='Supported by the cited source definitions, without assuming AI causation.' if ds else 'Research pending; no measured AI relationship asserted.',sourceIds=list(dict.fromkeys(s['sourceId'] for d in ds for s in d['sources']))),datasetIds=p['datasetIds'] if p else [],designId=None,verdict=p['verdict'] if p else 'hold',blockers=[] if p else ['Source investigation or populated extraction is incomplete.'],limitations=p['limitations'] if p else ['Not yet cleared for implementation.'],scoring={'type':'none','reason':'No defensible universal impact score.'},forecast={'type':'none','reason':'No validated forecasting model.'},review=dict(gates={f'G{i}':dict(status='unchecked',evidence=[],reason='Awaiting independent reviewer') for i in range(1,11)},score=None,scoreBreakdown={},reviewer=None,reviewedAt=None,datasetDigests={d['datasetId']:hashlib.sha256((ROOT/'datasets'/f"{d['datasetId']}.json").read_bytes()).hexdigest() for d in ds}),exactScope=p['proposedQuestion'] if p else c['question'],rationale=p['claim'] if p else 'Deep source investigation ongoing.',searchedSources=[s['url'] for d in ds for s in d['sources']],missingEvidence=[] if p else ['Populated reproducible primary-source dataset'],researcherVerdict=p['verdict'] if p else 'hold'))
